mapper.select:
select er.id, er.student_name student_name, er.score, er.exam_id exam_id, pr.`name` paper_name , pr. total_score paper_total_score, er.start_time start_time, er.end_time end_time, TIMESTAMPDIFF(MINUTE, er.start_time, er.end_time) duration from exam_records er left join paper pr on er.exam_id = pr.id where er.is_deleted = 0 and pr.is_deleted = 0 and er.`status` = '已批阅'
and pr.id=#{paperId}
order by er.score desc , duration asc
limit #{limit};
